CREATE OR REPLACE FUNCTION public.generate_trip_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  prefix text;
  next_number bigint;
BEGIN
  -- Assign on insert under a date-specific transaction lock so concurrent
  -- creators receive different references even if their previews matched.
  prefix := 'TRIP' || to_char(coalesce(NEW.loading_date::date, (now() AT TIME ZONE 'Asia/Manila')::date), 'YYMMDD');
  PERFORM pg_advisory_xact_lock(hashtextextended(prefix, 0));
  SELECT coalesce(max(substring(trip_reference FROM '^TRIP[0-9]{6}-([0-9]+)$')::bigint), 0) + 1
    INTO next_number FROM public.trips WHERE trip_reference LIKE prefix || '-%';
  NEW.trip_reference := prefix || '-' || next_number::text;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tracking_route_context_v1(p_assignment uuid, p_lock boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a jsonb; points jsonb; origin jsonb; plate text; dispatch text;
BEGIN
 a:=public.tracking_assignment_v1(p_assignment,p_lock); IF a IS NULL THEN RETURN NULL; END IF;
 IF p_lock THEN
  PERFORM 1 FROM public.trip_stops WHERE trip_id=(a->>'tripId')::uuid ORDER BY id FOR SHARE;
  PERFORM 1 FROM public.customer_stores WHERE id IN (SELECT store_id FROM public.trip_stops WHERE trip_id=(a->>'tripId')::uuid) ORDER BY id FOR SHARE;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',coalesce(st.name,'Destination'),'latitude',st.latitude,'longitude',st.longitude)
  ORDER BY s.stop_sequence,s.id),'[]'::jsonb) INTO points FROM public.trip_stops s
  LEFT JOIN public.customer_stores st ON st.id=s.store_id
  WHERE s.trip_id=(a->>'tripId')::uuid AND s.archived_at IS NULL AND coalesce(s.delivery_status,'PENDING') NOT IN ('COMPLETED','DELIVERED','CANCELLED');
 SELECT jsonb_build_object('id','position','latitude',l.latitude,'longitude',l.longitude,'captured_at',l.captured_at,
  'accuracy_meters',l.accuracy_meters,'revision',l.revision) INTO origin FROM public.trip_tracking_locations l
  WHERE l.assignment_id=p_assignment AND l.profile_id=(a->>'profileId')::uuid AND l.enabled AND l.captured_at IS NOT NULL;
 SELECT tr.plate_number,t.dispatch_number INTO plate,dispatch FROM public.trip_truck_assignments ta
  JOIN public.trucks tr ON tr.id=ta.truck_id JOIN public.trips t ON t.id=ta.trip_id WHERE ta.id=p_assignment;
 RETURN a||jsonb_build_object('destinations',points,'origin',origin,'plate_number',plate,'dispatch_number',dispatch,
  'context_token',md5(jsonb_build_array(a,points)::text));
END $function$

CREATE OR REPLACE FUNCTION public.planned_route_context_v1(p_assignment uuid, p_lock boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a jsonb; t public.trips%ROWTYPE; w public.warehouses%ROWTYPE; origin jsonb; points jsonb;
BEGIN
 a:=public.tracking_assignment_v1(p_assignment,p_lock);
 IF a IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO t FROM public.trips WHERE id=(a->>'tripId')::uuid;
 IF p_lock THEN
  PERFORM 1 FROM public.trip_stops WHERE trip_id=t.id ORDER BY id FOR SHARE;
  PERFORM 1 FROM public.customer_stores WHERE id IN(SELECT store_id FROM public.trip_stops WHERE trip_id=t.id) ORDER BY id FOR SHARE;
  SELECT * INTO w FROM public.warehouses WHERE id=t.warehouse_id FOR SHARE;
 ELSE SELECT * INTO w FROM public.warehouses WHERE id=t.warehouse_id; END IF;
 origin:=jsonb_build_object('id',w.id,'latitude',w.latitude,'longitude',w.longitude);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'latitude',st.latitude,'longitude',st.longitude,'stopSequence',s.stop_sequence)
  ORDER BY s.stop_sequence NULLS LAST,s.id),'[]'::jsonb) INTO points
 FROM public.trip_stops s LEFT JOIN public.customer_stores st ON st.id=s.store_id
 WHERE s.trip_id=t.id AND s.archived_at IS NULL;
 RETURN jsonb_build_object('id',p_assignment,'tripId',t.id,
  'active',t.archived_at IS NULL AND t.status NOT IN('COMPLETED','CANCELLED') AND EXISTS(SELECT FROM public.trip_truck_assignments WHERE id=p_assignment AND unassigned_at IS NULL),
  'origin',origin,'destinations',points,
  'context_token',md5(jsonb_build_array(a,t.warehouse_id,origin,points)::text));
END $function$
